(9075, 'koKR', 'Osłony nadgarstków są gotowe, $N.$B$B<Rimblat kłania się.>', 0),
(9077, 'koKR', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać napierśnik kościanej kosy.', 0),
(9078, 'koKR', 'Uważaj, jak w tym chodzisz. Jeszcze się pokaleczysz.', 0),
(9079, 'koKR', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać hełm kościanej kosy.', 0),
(9080, 'koKR', '<Rohan ociera pot z czoła.>$B$BNad tymi naramiennikami trochę się napracowałem! Tylko nie daj się zabić jak jakiś żółtodziób, $N.', 0),
(9081, 'koKR', 'Zakłada się je na stopy. Słuchaj, chyba znowu nie $gwęszyłeś:węszyłaś; w Dłoni Tyra, co?', 0),
(9082, 'koKR', 'W razie absolutnej konieczności te rękawice mogłyby pewnie posłużyć za broń. Noś je z dumą!', 0),
(9083, 'koKR', 'Pas jest gotowy, $N. $GWidziałeś:Widziałaś; kiedyś tak dobrą rzecz sprzedaną tak tanio?', 0),
(9084, 'koKR', 'Karwasze są gotowe, $N.$B$B<Rohan kłania się.>', 0),
(9086, 'koKR', 'Twoja tunika wędrowca snów jest gotowa, $N.', 0),
(9087, 'koKR', 'Zgodnie z obietnicą: osłony nóg wędrowca snów.$B$B<Rayne podaje ci zbroję.>', 0),
