(9113, 'koKR', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać diadem wiary.', 0),
(9114, 'koKR', 'Szaty są gotowe, $N. Poraź swym prawym ogniem tych, którzy chcieliby skrzywdzić nasz świat.', 0),
(9115, 'koKR', 'Szaty są gotowe, $N. Poraź swym prawym ogniem tych, którzy chcieliby skrzywdzić nasz świat.', 0),
(9116, 'koKR', 'Szaty są gotowe, $N. Poraź swym prawym ogniem tych, którzy chcieliby skrzywdzić nasz świat.', 0),
(9117, 'koKR', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać pas wiary.', 0),
(9118, 'koKR', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać więzy wiary.', 0),
(9120, 'koKR', 'Przez wszystkie dni mojego życia nigdy bym się nie spodziewał, że to zobaczę...$b$b<Ojcu Montoyowi chyba cieknie ślinka.>$b$bO tak, zostaniesz $gnagrodzony, mój drogi:nagrodzona, moja droga;. Sowicie $gnagrodzony:nagrodzona;. Dawaj to. Już!', 0),
(9229, 'koKR', 'To jego pierścień! Ale zniszczony. Nie było żadnych innych śladów Ramaladniego?$B$B<Korfax krzywi się.>$B$BTo nie wróży Ramaladniemu dobrze. Ale pierścień... może da się go uratować.', 0),
(9230, 'koKR', 'Sam Ramaladni nie zrobiłby tego lepiej! Oto pierścień, jak obiecałem.', 0);
