(9080, 'koKR', '<Rohan przygląda ci się podejrzliwie.>$B$B$GByłeś:Byłaś; ostatnio w Dłoni Tyra?', 0),
(9081, 'koKR', 'Po prostu przynieś mi materiały i przestań marnować mój czas.', 0),
(9082, 'koKR', 'Jak mam cokolwiek zrobić bez przedmiotów, o które prosiłem?', 0),
