INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15989, 3, 0, 'koKR', '%s wpada w szał!'),
(15990, 1, 0, 'koKR', 'Dobrze, że służycie mi tak wiernie. Wkrótce wszyscy będą służyć Królowi Liszowi, a na końcu zostaniecie nagrodzeni... o ile się nie zawahacie.'),
(15990, 3, 0, 'koKR', 'Wasze zabezpieczenia zawiodły! Natychmiast zajmijcie się tymi intruzami!'),
(15990, 6, 0, 'koKR', 'Kto śmie naruszać świętość mojej domeny? Strzeżcie się, każdy, kto tu wkracza, jest skazany na zgubę.'),
(15990, 15, 1, 'koKR', 'Dość! Mam już dosyć tych rozrywek!'),
(15990, 15, 2, 'koKR', 'Głupcy, za bardzo rozproszyliście swoje siły. Na wolność, moje sługi!'),
(16063, 1, 1, 'koKR', 'Może pójdą po rozum do głowy i uciekną, gdzie pieprz rośnie!'),
(16064, 1, 1, 'koKR', 'Dość się nasłuchałem twojego skamlenia. Zamknij jadaczkę, zanim ja ci ją zamknę!'),
(16065, 1, 0, 'koKR', 'Daj spokój, Zelieku, nie przepędzaj ich. Nie, zanim się z nimi zabawimy.'),
(30549, 1, 0, 'koKR', 'Dość tej paplaniny. Niech przyjdą! Zetrzemy ich kości na proch.'),
(30549, 1, 1, 'koKR', 'Zachowajcie gniew! Okiełznajcie wściekłość! Już wkrótce wszyscy będziecie mogli dać upust swojej frustracji.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12242, 'koKR', '%s wypatruje zombie do pożarcia!', '', 0),
(12348, 'koKR', '%s pożera wszystkie pobliskie zombie!', '', 0),
(12852, 'koKR', '', 'Wasze dawne życie, wasze śmiertelne pragnienia nic nie znaczą... jesteście teraz akolitami mistrza i będziecie służyć sprawie bez pytań! Największą chwałą jest umrzeć w służbie mistrza!', 0),
(12853, 'koKR', '', 'Mistrz mnie pomści!!', 0),
(12855, 'koKR', '', 'Żałosny nędzniku!', 0),
(12856, 'koKR', '', 'Zabijcie ich w imię mistrza!', 0),
(12857, 'koKR', '', 'Nie ukryjesz się przede mną!', 0),
(12858, 'koKR', '', 'Klęknij przede mną, robaku!', 0),
(12984, 'koKR', 'Kto śmie naruszać świętość mojej domeny? Strzeżcie się: każdy, kto tu wkracza, jest skazany na zgubę!', '', 0),
(12985, 'koKR', 'Głupcy! Myślicie, że zatriumfowaliście? Zbliżyliście się tylko o krok do otchłani!', '', 0),
(12986, 'koKR', 'Mam dość tych gier. Idźcie dalej, a skażę wasze dusze na niebyt!', '', 0),
(12987, 'koKR', 'Nie macie pojęcia, jakie okropności was czekają. Jeszcze nic nie widzieliście! Czeka na was zamarznięte serce Naxxramas!', '', 0),
(12988, 'koKR', 'Wkrótce wytępimy Przymierze i Hordę. Potem reszta Azeroth padnie przed potęgą mojej armii.', '', 0),
(12989, 'koKR', 'Najeźdźcy... tutaj?! ZNISZCZ ich, Kel\'Thuzadzie! Naxxramas nie może upaść!', '', 0),
(12990, 'koKR', 'Twoje siły są niemal gotowe, by uderzyć na twoich wrogów, mój panie.', '', 0),
(12991, 'koKR', 'Tak, mistrzu. Czas ich ostatecznej zagłady się zbliża... Co to?', '', 0),
(12992, 'koKR', 'Jak rozkażesz, mistrzu!', '', 0),
(12993, 'koKR', 'Chodźcie, bohaterowie... Z woli Króla Lisza zostaniecie zniszczeni.', '', 0),
(12994, 'koKR', 'Dobrze więc. Wojownicy zamarzniętych pustkowi, powstańcie! Rozkazuję wam walczyć, zabijać i umierać za waszego pana! Niech nikt nie przeżyje!', '', 0),
(12995, 'koKR', 'Módlcie się o litość!', '', 0),
(12996, 'koKR', 'Wykrzycz swój ostatni dech!', '', 0),
(12997, 'koKR', 'Nadszedł wasz koniec!', '', 0),
(12998, 'koKR', 'Mistrzu, potrzebuję pomocy!', '', 0),
(12999, 'koKR', 'Sługi, pachołkowie, żołnierze zimnego mroku! Usłuchajcie wezwania Kel\'Thuzada!', '', 0),
(13010, 'koKR', '', 'Broń się!', 0),
(13011, 'koKR', '', 'Touché...', 0),
(13013, 'koKR', '', 'Twoje życie należy do mnie!', 0),
(13014, 'koKR', '', 'Daj spokój, Zelieku, nie przepędzaj ich. Nie, zanim się z nimi zabawimy!', 0),
(13015, 'koKR', '', 'Mam nadzieję, że pożyją dość długo, żebym mogła się... przedstawić.', 0),
(13016, 'koKR', '', 'Pierwsze zabójstwo należy do mnie! Ktoś chce się założyć?', 0),
(13017, 'koKR', 'Twoja dusza jest teraz związana ze mną!', '', 0),
(13018, 'koKR', 'Nie ma ucieczki!', '', 0),
(13019, 'koKR', 'Aaargh! Nie... cieszcie... się! Wasze zwycięstwo jest puste, bo powrócę z mocą przekraczającą wasze wyobrażenia!', '', 0),
(13020, 'koKR', 'Zamrożę ci krew w żyłach!', '', 0),
(13021, 'koKR', 'Czeka cię mroczna pustka!', '', 0),
(13026, 'koKR', 'Jestem... pokonany.', '', 0),
(13028, 'koKR', 'Czekałem dość długo. Teraz staniesz przed żniwiarzem dusz.', '', 0),
(13030, 'koKR', 'W swej głupocie sami szukaliście zguby.', '', 0),
(13031, 'koKR', 'Zuchwale zlekceważyliście moce, których nie pojmujecie.', '', 0),
(13032, 'koKR', 'Ciężko walczyliście, by wedrzeć się do królestwa żniwiarza.', '', 0),
(13033, 'koKR', 'Teraz jest tylko jedno wyjście – kroczyć samotną ścieżką potępionych.', '', 0),
(13034, 'koKR', 'Dawaj, walcz, ty mały mazgaju!', '', 0),
(13035, 'koKR', 'Co za cholerne marnotrawstwo!', '', 0),
(13036, 'koKR', 'Następnym razem przyprowadź więcej kumpli!', '', 0),
(13037, 'koKR', 'Lubię mięsko dobrze przypieczone!', '', 0),
(13038, 'koKR', 'Do broni, obiboki! Mamy gości!', '', 0),
(13039, 'koKR', 'Dość się nasłuchałem twojego skamlenia! Zamknij jadaczkę, zanim ja ci ją zamknę!', '', 0),
(13040, 'koKR', 'Ale się ubawię, rozwalając te rozdziawione żonkile!', '', 0),
