(13044, 'koKR', '%s wydaje ostatnie tchnienie.', '', 0),
(13045, 'koKR', 'Zamknij oczy. Śpij.', '', 0),
(13046, 'koKR', 'Rasy tego świata zginą. To tylko kwestia czasu.', '', 0),
(13047, 'koKR', 'Widzę niekończące się cierpienie. Widzę męki. Widzę gniew. Widzę wszystko...', '', 0),
