(13098, 'koKR', 'Tak... powinno być.', '', 0),
(13099, 'koKR', 'Wybaczcie mi.', '', 0),
(13100, 'koKR', 'Nie mam wyboru, muszę być posłuszny!', '', 0),
(13101, 'koKR', 'Najeźdźcy, natychmiast zaniechajcie tej głupiej wyprawy! Zawróćcie, póki jeszcze możecie!', '', 0),
(13102, 'koKR', 'Może pójdą po rozum do głowy... i uciekną, gdzie pieprz rośnie.', '', 0),
(13103, 'koKR', 'Nie idźcie dalej! Zawróćcie, póki jeszcze jest czas!', '', 0),
